(function () {
'use strict';
var header = document.querySelector('.site-header');
var toggle = document.querySelector('.nav-toggle');
var nav = document.getElementById('site-nav');
var toTop = document.querySelector('.to-top');
function setMenu(open) {
toggle.setAttribute('aria-expanded', String(open));
toggle.setAttribute('aria-label', open ? (toggle.dataset.close || 'Close menu') : (toggle.dataset.open || 'Open menu'));
nav.classList.toggle('is-open', open);
}
if (toggle && nav) {
toggle.addEventListener('click', function () {
setMenu(toggle.getAttribute('aria-expanded') !== 'true');
});
nav.addEventListener('click', function (e) {
if (e.target.closest('a')) setMenu(false);
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') setMenu(false);
});
window.matchMedia('(min-width: 1001px)').addEventListener('change', function (mq) {
if (mq.matches) setMenu(false);
});
}
document.querySelectorAll('.has-sub').forEach(function (item) {
var btn = item.querySelector('.sub-toggle');
if (!btn) return;
btn.addEventListener('click', function (e) {
e.stopPropagation();
var open = !item.classList.contains('is-open');
item.classList.toggle('is-open', open);
btn.setAttribute('aria-expanded', String(open));
});
});
document.addEventListener('click', function (e) {
document.querySelectorAll('.has-sub.is-open').forEach(function (item) {
if (!item.contains(e.target)) { item.classList.remove('is-open'); item.querySelector('.sub-toggle').setAttribute('aria-expanded', 'false'); }
});
});
var ticking = false;
function onScroll() {
var y = window.scrollY;
if (header) header.classList.toggle('is-scrolled', y > 10);
if (toTop) toTop.classList.toggle('is-visible', y > 700);
ticking = false;
}
window.addEventListener('scroll', function () {
if (!ticking) { window.requestAnimationFrame(onScroll); ticking = true; }
}, { passive: true });
onScroll();
var faqItems = document.querySelectorAll('.faq details');
faqItems.forEach(function (item) {
item.addEventListener('toggle', function () {
if (!item.open) return;
faqItems.forEach(function (other) {
if (other !== item) other.open = false;
});
});
});
var logo = document.querySelector('.brand-logo img');
if (logo) {
var markMissing = function () { logo.parentNode.classList.add('is-missing'); };
if (logo.complete && logo.naturalWidth === 0) markMissing();
else logo.addEventListener('error', markMissing);
}
var PROMO_CODE = 'EGYPTONEX20';
document.querySelectorAll('[data-promo]').forEach(function (el) { el.textContent = PROMO_CODE; });
document.querySelectorAll('[data-copy]').forEach(function (btn) {
btn.addEventListener('click', function () {
var label = btn.textContent;
var done = function () {
btn.textContent = btn.dataset.copied || 'Copied!';
btn.classList.add('is-copied');
setTimeout(function () { btn.textContent = label; btn.classList.remove('is-copied'); }, 1800);
};
var fallback = function () {
var t = document.createElement('textarea');
t.value = PROMO_CODE; t.setAttribute('readonly', ''); t.style.position = 'absolute'; t.style.left = '-9999px';
document.body.appendChild(t); t.select();
try { document.execCommand('copy'); done(); } catch (e) {}
document.body.removeChild(t);
};
if (navigator.clipboard && navigator.clipboard.writeText) {
navigator.clipboard.writeText(PROMO_CODE).then(done, fallback);
} else { fallback(); }
});
});
var year = document.getElementById('year');
if (year) year.textContent = new Date().getFullYear();
})();
